def summarize(results):
    passed = results.count("passed")
    failed = results.count("failed")
    run = passed + failed
    return {
        "passed": passed,
        "failed": failed,
        "skipped": results.count("skipped"),
        "pass_rate": round(100 * passed / run) if run else 0,
    }
